from .common import *

def candidate(root):
 c=constants(root/'scripts/lint_connection_structural_boundaries.py')
 connection='l2000_connection/connection.py';lifecycle='l2000_connection/connection_lifecycle.py';sqlfile='impl/common/l2200_sql_dialect/sql_connection.py';backends=[f'impl/{p}/connection.py' for p in ['sqlite','postgres','mariadb']];lifefiles=backends+[f'impl/{p}/connection.py' for p in ['mongodb','neo4j']]
 stages=[S('structural_configuration',{'$option':'parameters','escape':'sql','template':'SELECT {} data'}),S('structural_entry',{'$option':'entryPoint','escape':'sql','template':'SELECT {} name'}),S('roles',"SELECT coalesce(json_extract(data,'$.connectionPath'),'l2000_connection/connection.py') connection_path,coalesce(json_extract(data,'$.lifecyclePath'),'l2000_connection/connection_lifecycle.py') lifecycle_path,coalesce(json_extract(data,'$.sqlPath'),'impl/common/l2200_sql_dialect/sql_connection.py') sql_path FROM structural_configuration"),S('top','SELECT * FROM a WHERE parent=0 AND kind IN (\'ClassDef\',\'FunctionDef\',\'AsyncFunctionDef\')',('__path','id')),
 S('last_classes',"SELECT c.*,CASE WHEN (SELECT name FROM structural_entry)='_lifecycle_violations' THEN c.id ELSE (SELECT min(x.id) FROM top x WHERE x.__path=c.__path AND x.kind='ClassDef' AND x.name=c.name) END AS class_order FROM top c WHERE c.kind='ClassDef' AND NOT EXISTS(SELECT 1 FROM top x WHERE x.__path=c.__path AND x.kind='ClassDef' AND x.name=c.name AND CASE WHEN (SELECT name FROM structural_entry) IN ('_connection_file_violations','_sql_connection_violations') THEN x.id<c.id WHEN (SELECT name FROM structural_entry)='_lifecycle_violations' THEN 0 ELSE x.id>c.id END)",('__path','id'),('__path','name')),
 S('all_bases',"SELECT c.__path,c.id,b.name,b.position FROM last_classes c JOIN a b ON b.__path=c.__path AND b.parent=c.id AND b.field='bases'",('__path','id')),
 S('bases',"SELECT c.__path,c.id,b.name,b.position FROM last_classes c JOIN a b ON b.__path=c.__path AND b.parent=c.id AND b.field='bases' WHERE b.kind IN ('Name','Attribute')",('__path','id')),
 S('struct_methods',"SELECT m.*,c.class_order FROM last_classes c JOIN methods m ON m.__path=c.__path AND m.parent=c.id",('__path','id')),
 S('self_connect',"SELECT DISTINCT m.__path,m.id FROM struct_methods m JOIN calls c ON c.__path=m.__path AND c.id BETWEEN m.id AND m.last WHERE c.callee_kind='Attribute' AND c.callee IN ('connect','connect_async') AND c.receiver_kind='Name' AND c.receiver_name='self'",('__path','id')),
 S('sync_targets',"""WITH RECURSIVE targets(__path,method,id) AS (
 SELECT m.__path,m.id,t.id FROM struct_methods m JOIN a n ON n.__path=m.__path AND n.id BETWEEN m.id AND m.last AND n.kind IN ('Assign','AnnAssign','AugAssign') JOIN a t ON t.__path=n.__path AND t.parent=n.id AND t.field IN ('target','targets')
 UNION ALL SELECT t.__path,t.method,n.id FROM targets t JOIN a p ON p.__path=t.__path AND p.id=t.id AND p.kind IN ('Tuple','List') JOIN a n ON n.__path=p.__path AND n.parent=p.id AND n.field='elts')
 SELECT DISTINCT t.__path,t.method,n.name FROM targets t JOIN a n ON n.__path=t.__path AND n.id=t.id JOIN a v ON v.__path=n.__path AND v.parent=n.id AND v.field='value' WHERE n.kind='Attribute' AND v.kind='Name' AND v.name='self' AND n.name IN ('_conn','_cursor','_introspector','_validator')""",('__path','method','name'))]
 rows=[]
 stages.append(S('line_metrics',"SELECT l.__path,coalesce(json_extract(p.data,'$.lineCounts.'||json_quote(l.__path)),CAST(l.source_lines AS INTEGER)) source_lines FROM lines l CROSS JOIN structural_configuration p",('__path',)))
 for path,code,label,maxname in [(connection,'CSB001','connection.py','CONNECTION_FILE_MAX_LINES'),(sqlfile,'CSB010','sql_connection.py','SQL_CONNECTION_FILE_MAX_LINES'),*[(p,'CSB020',p,'BACKEND_CONNECTION_FILE_MAX_LINES') for p in backends]]:
  rows.append(row(code,q(label+' has ')+'||l.source_lines||'+q(' lines; target is <= '+str(c[maxname])),'a n JOIN line_metrics l ON l.__path=n.__path',f"n.kind='Module' AND n.__path={q(path)} AND CAST(l.source_lines AS INTEGER)>{c[maxname]}",phase=0))
 for path,code,constant,msg in [(connection,'CSB002','CONNECTION_RESIDUAL_SYMBOLS',"'residual non-state/lazy symbol '||n.name_repr||' still lives in connection.py'"),(sqlfile,'CSB012','SQL_RESIDUAL_SYMBOLS',"'residual SQL service candidate '||n.name_repr||' still lives in sql_connection.py'"),*[(p,'CSB021','BACKEND_MIXIN_SYMBOLS',"'backend mixin bucket '||n.name_repr||' still lives in connection.py'") for p in backends]]:
  rows.append(row(code,msg,'top n',f'n.__path={q(path)} AND n.name IN {literals(c[constant])}',phase=1))
 stages.append(S('bad_bases',f"SELECT __path,id,group_concat(name,', ') names FROM (SELECT * FROM bases WHERE name NOT IN {literals(c['ALLOWED_DATABASE_CORE_BASES'])} ORDER BY name) GROUP BY __path,id",('__path','id')))
 rows.append(row('CSB003',"'_DatabaseConnectionCore still inherits non-state ownership mixins: '||b.names",'last_classes n JOIN bad_bases b ON b.__path=n.__path AND b.id=n.id',f'n.__path={q(connection)} AND n.name=\'_DatabaseConnectionCore\'',phase=2))
 rows.append(row('CSB011',"'sql_connection.py has '||(SELECT count(*) FROM top t WHERE t.__path=n.__path)||' top-level blocks; target is <= "+str(c['SQL_TOP_LEVEL_BLOCK_MAX'])+"'",'a n',f"n.kind='Module' AND n.__path={q(sqlfile)} AND (SELECT count(*) FROM top t WHERE t.__path=n.__path)>{c['SQL_TOP_LEVEL_BLOCK_MAX']}",phase=0,order='0.1'))
 rows.append(row('CSB013',"'_SqlConnectionCore has '||(CASE WHEN (SELECT name FROM structural_entry)='_sql_connection_violations' THEN (SELECT count(*) FROM all_bases b WHERE b.__path=n.__path AND b.id=n.id) ELSE (SELECT count(*) FROM bases b WHERE b.__path=n.__path AND b.id=n.id) END)||' direct bases; target is <= "+str(c['SQL_CORE_DIRECT_BASE_MAX'])+"'",'last_classes n',f"n.__path={q(sqlfile)} AND n.name='_SqlConnectionCore' AND (CASE WHEN (SELECT name FROM structural_entry)='_sql_connection_violations' THEN (SELECT count(*) FROM all_bases b WHERE b.__path=n.__path AND b.id=n.id) ELSE (SELECT count(*) FROM bases b WHERE b.__path=n.__path AND b.id=n.id) END)>{c['SQL_CORE_DIRECT_BASE_MAX']}",phase=2))
 lifecycle_path=f"CASE WHEN EXISTS(SELECT 1 FROM gate WHERE __path={q(lifecycle)}) THEN {q(lifecycle)} ELSE {q(connection)} END"
 rows.append(row('CSB030',"'_ConnectionLifecycleMixin.'||n.name||' auto-opens driver state'",'struct_methods n JOIN self_connect s ON s.__path=n.__path AND s.id=n.id',f"n.__path=({lifecycle_path}) AND n.class_name='_ConnectionLifecycleMixin' AND n.name IN ('__enter__','__aenter__') AND ((SELECT name FROM structural_entry)!='_lifecycle_violations' OR (n.parent=(SELECT min(c.id) FROM top c WHERE c.__path=n.__path AND c.name='_ConnectionLifecycleMixin' AND c.kind='ClassDef') AND NOT EXISTS(SELECT 1 FROM methods earlier WHERE earlier.__path=n.__path AND earlier.parent=n.parent AND earlier.name=n.name AND earlier.id<n.id)))",phase=3,order="CASE WHEN (SELECT name FROM structural_entry)='_lifecycle_violations' THEN CASE n.name WHEN '__enter__' THEN 0 ELSE 1 END ELSE n.id END"))
 lifecond=f"n.__path IN {literals(lifefiles)} AND (substr(n.class_name,-10)='Connection' OR substr(n.class_name,-14)='ConnectionCore')"
 rows.append(row('CSB031',"n.class_name||'.'||n.name||' overrides centralized lifecycle policy'",'struct_methods n',lifecond+f" AND n.name IN {literals(c['CONTEXT_MANAGER_METHODS'])}",phase=4,order='n.class_order+n.position*0.001'))
 stages.append(S('target_names',"SELECT __path,method,group_concat(name,', ') AS names FROM (SELECT * FROM sync_targets ORDER BY name) GROUP BY __path,method",('__path','method')))
 rows.append(row('CSB032',"n.class_name||'.connect_async mutates sync state: '||t.names",'struct_methods n JOIN target_names t ON t.__path=n.__path AND t.method=n.id',lifecond+" AND n.name='connect_async'",phase=4,order='n.class_order+n.position*0.001+0.00001'))
 rows.append(row('CSB033',"n.class_name||'.'||n.name||' opens driver state outside lifecycle boundary'",'struct_methods n JOIN self_connect s ON s.__path=n.__path AND s.id=n.id',lifecond+f" AND n.name NOT IN {literals(c['ALLOWED_CONNECT_CALLERS'])}",phase=4,order='n.class_order+n.position*0.001+0.00002'))
 query="SELECT *,CASE WHEN issue='CSB030' THEN 3 WHEN issue IN ('CSB031','CSB032','CSB033') THEN 4 WHEN path="+q(connection)+" THEN 0 WHEN path="+q(sqlfile)+" THEN 1 ELSE 2 END api_group FROM ("+' UNION ALL '.join(rows)+')'
 for original,column in [(connection,'connection_path'),(lifecycle,'lifecycle_path'),(sqlfile,'sql_path')]:query=query.replace(q(original),'(SELECT '+column+' FROM roles)')
 families={'_connection_file_violations':['CSB001','CSB002','CSB003'],'_sql_connection_violations':['CSB010','CSB011','CSB012','CSB013'],'_backend_file_violations':['CSB020','CSB021'],'_lifecycle_violations':['CSB030','CSB031','CSB032','CSB033']}
 query={'$option':'entryPoint','cases':{entry:'SELECT * FROM ('+query+') WHERE issue IN '+literals(codes) for entry,codes in families.items()},'default':query}
 return document('connection_structural_boundaries',[clause('connection-structure',stages,query,partition=False)], [connection,lifecycle,sqlfile,*lifefiles])
